```python
from collections import defaultdict

def max_flow(edges):
    # Initialize the flow network
    n = max(node for _, _, node in edges) + 1
    graph = defaultdict(dict)
    for s, t, cap in edges:
        graph[s][t] = {'capacity': cap, 'flow': 0}
        graph[t][s] = {'capacity': 0, 'flow': 0}

    # Initialize the residual network
    residual_graph = defaultdict(dict)
    for s, t, cap in edges:
        residual_graph[s][t] = {'capacity': cap, 'flow': 0}
        residual_graph[t][s] = {'capacity': 0, 'flow': 0}

    # Initialize the augmenting path
    def dfs(node, prev_node, flow):
        if node == 's':
            return flow
        for t, flow_ in graph[node].items():
            if flow_['capacity'] > flow_['flow'] and t != prev_node:
                new_flow = min(flow, flow_)['capacity'] - flow_['flow']
                if dfs(t, node, new_flow):
                    graph[node][t]['flow'] += new_flow
                    graph[t][node]['flow'] -= new_flow
                    return new_flow
        return 0

    # Find the augmenting path
    while True:
        flow = dfs('t', None, float('inf'))
        if not flow:
            break

    # Calculate the maximum flow
    max_flow = 0
    for s, t, cap in edges:
        max_flow += min(graph[s][t]['flow'], graph[t][s]['flow']) * cap

    return max_flow
```

You can use this function by passing a list of edges as input, where each edge is a tuple of three elements: the source node, the target node, and the capacity of the edge. For example:

